{"path": "rest_api.py", "content": "import json


class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        for user in (database or {}).get("users", []):
            self.users[user["name"]] = {
                "name": user["name"],
                "owes": dict(user.get("owes", {})),
                "owed_by": dict(user.get("owed_by", {})),
            }

    def _user_object(self, name):
        user = self.users[name]
        balance = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return {
            "name": name,
            "owes": dict(user["owes"]),
            "owed_by": dict(user["owed_by"]),
            "balance": balance,
        }

    def _users_response(self, names):
        return json.dumps(
            {"users": [self._user_object(n) for n in sorted(names)]}
        )

    @staticmethod
    def _parse(payload):
        if payload is None:
            return None
        if isinstance(payload, (str, bytes)):
            return json.loads(payload) if payload else None
        return payload

    def get(self, url, payload=None):
        data = self._parse(payload)
        if url == "/users":
            if data and "users" in data:
                names = [n for n in data["users"] if n in self.users]
            else:
                names = list(self.users)
            return self._users_response(names)
        raise ValueError(f"unknown url: {url}")

    def post(self, url, payload=None):
        data = self._parse(payload) or {}
        if url == "/add":
            name = data["user"]
            if name in self.users:
                raise ValueError(f"user already exists: {name}")
            self.users[name] = {"name": name, "owes": {}, "owed_by": {}}
            return json.dumps(self._user_object(name))
        if url == "/iou":
            lender_name = data["lender"]
            borrower_name = data["borrower"]
            amount = data["amount"]
            if lender_name not in self.users or borrower_name not in self.users:
                raise ValueError("unknown user")
            if lender_name == borrower_name:
                raise ValueError("lender and borrower must differ")
            self._add_debt(lender_name, borrower_name, amount)
            return self._users_response([lender_name, borrower_name])
        raise ValueError(f"unknown url: {url}")

    def _add_debt(self, lender_name, borrower_name, amount):
        lender = self.users[lender_name]
        borrower = self.users[borrower_name]
        # Net debt from borrower to lender, positive means borrower owes lender.
        net = (
            lender["owed_by"].pop(borrower_name, 0)
            - lender["owes"].pop(borrower_name, 0)
            + amount
        )
        borrower["owes"].pop(lender_name, None)
        borrower["owed_by"].pop(lender_name, None)
        if net > 0:
            lender["owed_by"][borrower_name] = net
            borrower["owes"][lender_name] = net
        elif net < 0:
            lender["owes"][borrower_name] = -net
            borrower["owed_by"][lender_name] = -net
